good_tf:
resource "aws_s3_bucket" "data" {
  bucket = "example-data-bucket"
}

resource "aws_s3_bucket_public_access_block" "data" {
  bucket                  = aws_s3_bucket.data.id
  block_public_acls       = true # FIX: reject new public ACLs
  block_public_policy     = true # FIX: reject public bucket policies
  ignore_public_acls      = true # FIX: ignore existing public ACLs
  restrict_public_buckets = true # FIX: only AWS principals in this account
}

resource "aws_s3_bucket_ownership_controls" "data" { # FIX: disable ACLs entirely
  bucket = aws_s3_bucket.data.id
  rule {
    object_ownership = "BucketOwnerEnforced" # FIX: bucket owner owns every object
  }
}
